--- a/internal/server/routes_ratelimit.go
+++ b/internal/server/routes_ratelimit.go
@@ -63,15 +63,10 @@ func (rl *rateLimiter) allow(key string, limit int, window time.Duration) bool {
 	return true
 }

-var (
-	authLimiter = newRateLimiter()
-	linkLimiter = newRateLimiter()
-)
-
-func withAuthRateLimit(h http.HandlerFunc) http.HandlerFunc {
+func withAuthRateLimit(rl *rateLimiter, h http.HandlerFunc) http.HandlerFunc {
