+		if !rl.allow(ip, 10, time.Minute) {
 			writeJSON(w, http.StatusTooManyRequests, map[string]string{"error": "rate limit exceeded"})
 			return
 		}
@@ -79,14 +74,14 @@ func withAuthRateLimit(h http.HandlerFunc) http.HandlerFunc {
 	}
 }

-func withLinkRateLimit(h http.HandlerFunc) http.HandlerFunc {
+func withLinkRateLimit(rl *rateLimiter, h http.HandlerFunc) http.HandlerFunc {
 	return func(w http.ResponseWriter, r *http.Request) {
 		userID, ok := session.UserID(r)
 		if !ok {
 			h(w, r)
 			return
 		}
-		if !linkLimiter.allow(userID, 30, time.Hour) {
+		if !rl.allow(userID, 30, time.Hour) {
 			writeJSON(w, http.StatusTooManyRequests, map[string]string{"error": "rate limit exceeded"})
 			return
 		}

